import{_ as a,o as i,c as o,a2 as l}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Installazione","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/installazione.md","filePath":"user-guide/installazione.md"}'),n={name:"user-guide/installazione.md"};function t(r,e,s,d,c,p){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="installazione" tabindex="-1">Installazione <a class="header-anchor" href="#installazione" aria-label="Permalink to &quot;Installazione&quot;">​</a></h1><p>L&#39;app desktop è distribuita per macOS, Windows e Linux. Le modalità di distribuzione (installer firmati, aggiornamenti automatici) sono definite da <code>docs/release/README.md</code>: qui i requisiti e i passi generali.</p><table tabindex="0"><thead><tr><th>Sistema</th><th>Requisiti</th><th>Note</th></tr></thead><tbody><tr><td>macOS</td><td>Versione recente supportata da WebKit/WKWebView</td><td>Trascinare l&#39;app in <em>Applicazioni</em>. Al primo avvio confermare l&#39;apertura se richiesto.</td></tr><tr><td>Windows</td><td>Windows 10/11 con <strong>WebView2 Runtime</strong></td><td>L&#39;installer registra anche lo schema <code>clarae://</code> (necessario per aprire link e per il login).</td></tr><tr><td>Linux</td><td><code>webkit2gtk-4.1</code> installato</td><td>Il pacchetto registra <code>x-scheme-handler/clarae</code> nel file <code>.desktop</code>.</td></tr></tbody></table><p><strong>Per le <a href="./applicazioni.html">applicazioni</a> nella scheda</strong> servono il <em>WebView2 Runtime</em> dalla versione 1.0.2210.55 (Windows) e <code>webkit2gtk-4.1</code> dalla versione 2.40 (Linux). Se mancano, le applicazioni si aprono nel browser di sistema; il resto dell&#39;app funziona lo stesso.</p><h2 id="primo-avvio" tabindex="-1">Primo avvio <a class="header-anchor" href="#primo-avvio" aria-label="Permalink to &quot;Primo avvio&quot;">​</a></h2><ol><li>Avviate l&#39;app: compare la schermata <strong>Apri un vault</strong>.</li><li>Scegliete una cartella esistente (anche una cartella di note creata con un altro editor) oppure una cartella vuota: diventerà il vostro vault.</li><li>Il cloud non serve per iniziare: tutto funziona offline.</li></ol><h2 id="dove-l-app-salva-i-dati" tabindex="-1">Dove l&#39;app salva i dati <a class="header-anchor" href="#dove-l-app-salva-i-dati" aria-label="Permalink to &quot;Dove l&#39;app salva i dati&quot;">​</a></h2><ul><li><strong>Le note</strong> restano nella cartella del vault, come file normali: potete aprirle con altri editor e includerle nei vostri backup.</li><li>Nella cartella nascosta <code>.clarae/</code> del vault: impostazioni dell&#39;editor, aspetto, scorciatoie, layout dei pannelli, segnalibri, snapshot locali. Non modificatela a mano mentre l&#39;app è aperta.</li><li>Nella cartella dati dell&#39;applicazione (fuori dal vault): indice di ricerca (ricostruibile), stato di sincronizzazione, log, e il token di accesso al cloud nel <strong>portachiavi</strong> del sistema.</li></ul><h2 id="aggiornare-e-disinstallare" tabindex="-1">Aggiornare e disinstallare <a class="header-anchor" href="#aggiornare-e-disinstallare" aria-label="Permalink to &quot;Aggiornare e disinstallare&quot;">​</a></h2><p>Seguite le istruzioni del canale di distribuzione in uso: le build pubblicate non hanno l&#39;aggiornamento automatico, quindi ogni nuova versione si installa a mano sopra la precedente. Se arrivate dalla versione 1.x, leggete <a href="#aggiornare-dalla-1x">Aggiornare dalla 1.x</a>. Disinstallare l&#39;app <strong>non</strong> cancella i vault. Per rimuovere anche i dati locali eliminate la cartella dati dell&#39;applicazione; il portachiavi del sistema contiene la voce del token (rimuovibile da lì).</p><h2 id="aggiornare-dalla-1-x" tabindex="-1">Aggiornare dalla 1.x <a class="header-anchor" href="#aggiornare-dalla-1-x" aria-label="Permalink to &quot;Aggiornare dalla 1.x&quot;">​</a></h2><p>La 1.5 cambia il nome del prodotto: prima si chiamava MemoBrain Notes. Le funzioni non cambiano e i vault restano come sono. Le build della 1.x non hanno l&#39;aggiornamento automatico, quindi la 1.5 si installa a mano.</p><ol><li><strong>Chiudete la vecchia app</strong> prima di avviare la nuova. Se è ancora aperta, la nuova mostra un messaggio che chiede di chiuderla e non parte: due istanze sulla stessa cartella dati non sono sicure.</li><li><strong>Installate la nuova app</strong> e togliete la vecchia, dove l&#39;installer non lo fa da solo: <ul><li><strong>macOS:</strong> trascinate <em>Clarae notanda</em> in <em>Applicazioni</em>. È un&#39;app diversa: <em>MemoBrain Notes</em> resta dov&#39;è e va spostata nel Cestino a mano.</li><li><strong>Windows:</strong> l&#39;installer rimuove da solo l&#39;installazione precedente. Se la vecchia app è aperta vi chiede di chiuderla e di riprovare.</li><li><strong>Linux:</strong> il pacchetto <code>.deb</code> sostituisce quello precedente. Un <strong>AppImage</strong> della 1.x non viene rimosso: eliminate il vecchio file.</li></ul></li><li><strong>Al primo avvio</strong> la nuova app prende da sola la cartella dati (vault recenti, impostazioni dell&#39;app), la sessione e le chiavi dei vault privati dal portachiavi del sistema: non dovete accedere di nuovo né reinserire passphrase. I link <code>memobrain://</code> già scritti nelle note continuano ad aprirsi.</li><li><strong>Nei vault</strong> la cartella nascosta si chiama ora <code>.clarae/</code> (prima <code>.memobrain/</code>). Un vault non collegato al cloud sposta lì le impostazioni quando lo aprite. Un vault <strong>collegato</strong> tiene le impostazioni sincronizzate in <code>.memobrain/</code> finché non parte lo spostamento: dalla 1.7 parte da solo, dopo che il client ha letto il profilo del server, a meno che l&#39;amministratore non lo abbia spento nel Config Profile (<code>features.config_dir_v2</code>) perché un dispositivo con la 1.4 le legge ancora nella cartella vecchia. Vedere entrambe le cartelle è normale. Se avete ancora un dispositivo con la 1.4 sullo stesso vault, aggiornatelo prima: dopo lo spostamento non vede più le impostazioni e ne ricrea di nuove. Non cancellatene nessuna a mano. Indice, stato di sincronizzazione, snapshot e layout dei pannelli passano subito a <code>.clarae/</code>.</li><li><strong>Disegni e presentazioni</strong> della 1.x si aprono come prima. I nomi nuovi si scrivono solo quando li modificate; un dispositivo che ha ancora la 1.4 non riconosce le impostazioni salvate dalla 1.5 (formule modificabili e ordine delle diapositive in un disegno; slide escluse, «ricomincia alla fine» e note del relatore in una presentazione). Aggiornate tutti i dispositivi.</li><li><strong>Nel browser</strong> il profilo del workbench si porta da solo ai nuovi nomi alla prima apertura. Chiudete prima le schede del workbench aperte con la versione precedente: finché una è aperta il workbench nuovo non parte.</li><li><strong>Su macOS e Linux</strong> ciò che il motore web dell&#39;app tiene per conto suo (per esempio l&#39;elenco degli strumenti recenti dei disegni) può ripartire vuoto. Tornare alla 1.4.0 sullo stesso dispositivo non è previsto.</li></ol><p>Se l&#39;amministratore ha un&#39;installazione della 1.x del cloud, non cambia nulla per voi: la 1.5 e il cloud della 1.x si parlano. Per gli amministratori c&#39;è una <a href="./../admin-guide/migrazione-clarae.html">guida di migrazione</a>.</p>',14)])])}const g=a(n,[["render",t]]);export{m as __pageData,g as default};
